CREATE OR REPLACE FUNCTION public.gallaspy_activate_standard_member_v2(p_user_id uuid, p_agreement_version text, p_agreement_sha256 text, p_rules_version text, p_rules_sha256 text, p_waiver_version text, p_waiver_sha256 text, p_billing_version text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_attempt public.gallaspy_standard_enrollment_attempts%ROWTYPE;
  v_subscription public.gallaspy_standard_subscriptions%ROWTYPE;
  v_number text;
  v_type text;
  v_status text;
  v_dues integer;
  v_initiation integer;
  v_initial integer;
  v_interval text;
  v_tries integer := 0;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'User ID required';
  END IF;

  -- Serialize activation for this account.
  PERFORM 1
  FROM auth.users
  WHERE id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User does not exist';
  END IF;

  SELECT *
  INTO v_attempt
  FROM public.gallaspy_standard_enrollment_attempts
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Enrollment attempt required';
  END IF;

  IF v_attempt.selected_plan NOT IN ('monthly', 'annual')
     OR v_attempt.selected_plan IS NULL THEN
    RAISE EXCEPTION 'Valid enrollment plan required';
  END IF;

  IF v_attempt.selected_plan = 'monthly' THEN
    v_dues := 10000;
    v_initiation := 25000;
    v_initial := 35000;
    v_interval := 'monthly';
  ELSE
    v_dues := 100000;
    v_initiation := 0;
    v_initial := 100000;
    v_interval := 'annual';
  END IF;

  IF v_attempt.renewal_amount_cents IS DISTINCT FROM v_dues
    OR v_attempt.initiation_fee_cents IS DISTINCT FROM v_initiation
    OR v_attempt.initial_payment_cents IS DISTINCT FROM v_initial
    OR v_attempt.renewal_interval IS DISTINCT FROM v_interval
  THEN
    RAISE EXCEPTION 'Enrollment pricing mismatch';
  END IF;

  -- Require a trusted, exact document version and hash.
  IF NULLIF(btrim(p_agreement_version), '') IS NULL
    OR NULLIF(btrim(p_rules_version), '') IS NULL
    OR NULLIF(btrim(p_waiver_version), '') IS NULL
    OR NULLIF(btrim(p_billing_version), '') IS NULL
    OR p_agreement_sha256 !~ '^[a-fA-F0-9]{64}$'
    OR p_rules_sha256 !~ '^[a-fA-F0-9]{64}$'
    OR p_waiver_sha256 !~ '^[a-fA-F0-9]{64}$'
    OR p_agreement_sha256 IS NULL
    OR p_rules_sha256 IS NULL
    OR p_waiver_sha256 IS NULL
  THEN
    RAISE EXCEPTION 'Trusted document identity required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.gallaspy_membership_legal_acceptances l
    WHERE l.user_id = p_user_id
      AND l.enrollment_attempt_id = v_attempt.id
      AND l.membership_plan = v_attempt.selected_plan
      AND l.membership_agreement_version = p_agreement_version
      AND lower(l.membership_agreement_sha256) = lower(p_agreement_sha256)
      AND l.club_rules_version = p_rules_version
      AND lower(l.club_rules_sha256) = lower(p_rules_sha256)
      AND l.activity_waiver_version = p_waiver_version
      AND lower(l.activity_waiver_sha256) = lower(p_waiver_sha256)
      AND l.legal_terms_accepted = true
      AND l.electronic_signature_consent = true
      AND length(btrim(l.signed_full_name)) > 0
      AND l.accepted_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Matching signed legal acceptance required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.gallaspy_membership_billing_consents b
    WHERE b.user_id = p_user_id
      AND b.enrollment_attempt_id = v_attempt.id
      AND b.membership_plan = v_attempt.selected_plan
      AND b.initiation_fee_cents = v_initiation
      AND b.initial_payment_cents = v_initial
      AND b.renewal_amount_cents = v_dues
      AND b.renewal_interval = v_interval
      AND b.currency = 'USD'
      AND b.billing_disclosure_version = p_billing_version
      AND b.billing_consent_accepted = true
      AND b.accepted_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Matching billing consent required';
  END IF;

  SELECT *
  INTO v_subscription
  FROM public.gallaspy_standard_subscriptions
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Subscription record required';
  END IF;

  IF v_subscription.membership_plan <> v_attempt.selected_plan
    OR v_subscription.renewal_amount_cents <> v_dues
    OR v_subscription.renewal_interval <> v_interval
    OR v_subscription.currency <> 'USD'
    OR v_subscription.subscription_status NOT IN ('active', 'canceled')
    OR v_subscription.square_subscription_id IS NULL
    OR v_subscription.square_subscription_id
       IS DISTINCT FROM v_attempt.square_subscription_id
    OR v_subscription.current_period_start IS NULL
    OR v_subscription.current_period_end IS NULL
    OR v_subscription.current_period_start > now()
    OR v_subscription.current_period_end <= now()
  THEN
    RAISE EXCEPTION 'Verified current subscription required';
  END IF;

  -- Require a completed dues payment for this exact period.
  IF NOT EXISTS (
    SELECT 1
    FROM public.gallaspy_subscription_payments p
    WHERE p.subscription_id = v_subscription.id
      AND p.payment_status = 'completed'
      AND p.refunded_amount_cents = 0
      AND p.verified_at IS NOT NULL
      AND p.verified_at <= now()
      AND p.refunded_amount_cents = 0
      AND p.verified_at IS NOT NULL
      AND p.verified_at <= now()
      AND p.amount_cents = v_dues
      AND p.currency = 'USD'
      AND p.billing_period_start =
        v_subscription.current_period_start
      AND p.billing_period_end =
        v_subscription.current_period_end
  ) THEN
    RAISE EXCEPTION 'Completed current-period dues required';
  END IF;

  -- Annual members have no initiation fee.
  -- New monthly members require a separate verified $250 charge.
  IF v_attempt.selected_plan = 'monthly'
    AND NOT EXISTS (
      SELECT 1
      FROM public.gallaspy_membership_initiation_payments i
      WHERE i.user_id = p_user_id
        AND i.enrollment_attempt_id = v_attempt.id
        AND i.membership_plan = 'monthly'
        AND i.amount_cents = 25000
        AND i.currency = 'USD'
        AND i.payment_status = 'completed'
        AND i.refunded_amount_cents = 0
        AND i.verified_at <= now()
        AND i.refunded_amount_cents = 0
        AND i.verified_at <= now()
        AND i.square_payment_id IS NOT NULL
        AND i.verified_at IS NOT NULL
    )
  THEN
    RAISE EXCEPTION 'Verified $250 initiation payment required';
  END IF;

  SELECT membership_type, membership_status, membership_number
  INTO v_type, v_status, v_number
  FROM public.gallaspy_memberships
  WHERE user_id = p_user_id;

  IF v_type = 'falcon_society' OR v_status = 'suspended' THEN
    RAISE EXCEPTION 'Membership requires administrative review';
  END IF;

  IF v_number IS NOT NULL
    AND v_number !~ '^GGC-[0-9]{6,}$' THEN
    RAISE EXCEPTION 'Existing membership number requires review';
  END IF;

  IF v_number IS NULL THEN
    LOOP
      v_tries := v_tries + 1;

      IF v_tries > 100 THEN
        RAISE EXCEPTION 'Unable to allocate membership number';
      END IF;

      v_number := public.gallaspy_next_standard_member_number();

      EXIT WHEN NOT EXISTS (
        SELECT 1
        FROM public.gallaspy_memberships
        WHERE membership_number = v_number
      );
    END LOOP;
  END IF;

  INSERT INTO public.gallaspy_memberships (
    user_id, membership_number, membership_type,
    membership_status, approved_at
  )
  VALUES (
    p_user_id, v_number, 'standard', 'approved', now()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    membership_number = EXCLUDED.membership_number,
    membership_status = 'approved',
    approved_at = COALESCE(
      public.gallaspy_memberships.approved_at, now()
    ),
    updated_at = now();

  RETURN v_number;
END;
$function$

CREATE OR REPLACE FUNCTION public.gallaspy_record_verified_dues_v4(p_user_id uuid, p_square_subscription_id text, p_square_payment_id text, p_square_invoice_id text, p_amount_cents integer, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_paid_at timestamp with time zone, p_verified_at timestamp with time zone, p_subscription_start timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_sub public.gallaspy_standard_subscriptions%ROWTYPE;
  v_existing public.gallaspy_subscription_payments%ROWTYPE;
  v_expected_amount integer;
  v_interval_months integer;
  v_month_offset integer;
  v_anchor date;
  v_start date;
  v_end date;
  v_result text;
BEGIN
  IF p_user_id IS NULL
    OR p_square_subscription_id IS NULL
    OR p_square_payment_id IS NULL
    OR p_square_invoice_id IS NULL
    OR p_amount_cents IS NULL
    OR p_period_start IS NULL
    OR p_period_end IS NULL
    OR p_paid_at IS NULL
    OR p_verified_at IS NULL
    OR p_subscription_start IS NULL
  THEN
    RAISE EXCEPTION 'Complete verified payment evidence required';
  END IF;

  PERFORM 1
  FROM auth.users
  WHERE id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Membership account unavailable';
  END IF;

  SELECT *
  INTO v_sub
  FROM public.gallaspy_standard_subscriptions
  WHERE user_id = p_user_id
    AND square_subscription_id = p_square_subscription_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Linked membership subscription required';
  END IF;

  IF v_sub.membership_plan = 'monthly' THEN
    v_expected_amount := 10000;
    v_interval_months := 1;
  ELSIF v_sub.membership_plan = 'annual' THEN
    v_expected_amount := 100000;
    v_interval_months := 12;
  ELSE
    RAISE EXCEPTION 'Invalid membership plan';
  END IF;

  IF p_amount_cents <> v_expected_amount
    OR v_sub.renewal_amount_cents <> v_expected_amount
    OR v_sub.renewal_interval <> v_sub.membership_plan
    OR v_sub.currency <> 'USD'
  THEN
    RAISE EXCEPTION 'Membership renewal pricing mismatch';
  END IF;

  SELECT *
  INTO v_existing
  FROM public.gallaspy_subscription_payments
  WHERE square_payment_id = p_square_payment_id;

  IF FOUND THEN
    IF v_existing.subscription_id IS DISTINCT FROM v_sub.id
      OR v_existing.square_invoice_id IS DISTINCT FROM p_square_invoice_id
      OR v_existing.billing_period_start IS DISTINCT FROM p_period_start
      OR v_existing.billing_period_end IS DISTINCT FROM p_period_end
      OR v_existing.amount_cents IS DISTINCT FROM p_amount_cents
      OR v_existing.currency <> 'USD'
      OR v_existing.payment_status <> 'completed'
      OR v_existing.refunded_amount_cents IS DISTINCT FROM 0
      OR v_existing.paid_at IS DISTINCT FROM p_paid_at
      OR v_existing.verified_at IS NULL
    THEN
      RAISE EXCEPTION 'Payment replay requires reconciliation';
    END IF;

    RETURN 'duplicate';
  END IF;

  IF v_sub.subscription_status NOT IN (
    'pending', 'active', 'past_due'
  )
    OR v_sub.cancel_at_period_end
  THEN
    RAISE EXCEPTION 'Subscription is not eligible for renewal';
  END IF;

  IF p_period_start >= p_period_end
    OR p_period_start > now()
    OR p_period_end <= now()
    OR p_paid_at < p_period_start
    OR p_paid_at >= p_period_end
    OR p_paid_at > now()
    OR p_verified_at < p_paid_at
    OR p_verified_at > now()
  THEN
    RAISE EXCEPTION 'Invalid verified renewal period';
  END IF;

  v_anchor := (p_subscription_start AT TIME ZONE 'UTC')::date;
  v_start := (p_period_start AT TIME ZONE 'UTC')::date;
  v_end := (p_period_end AT TIME ZONE 'UTC')::date;

  IF (p_subscription_start AT TIME ZONE 'UTC')::time <> time '00:00'
    OR (p_period_start AT TIME ZONE 'UTC')::time <> time '00:00'
    OR (p_period_end AT TIME ZONE 'UTC')::time <> time '00:00'
  THEN
    RAISE EXCEPTION 'UTC billing boundaries required';
  END IF;

  v_month_offset :=
    (
      extract(year FROM v_start)::integer
      - extract(year FROM v_anchor)::integer
    ) * 12
    + extract(month FROM v_start)::integer
    - extract(month FROM v_anchor)::integer;

  IF v_month_offset < 0
    OR mod(v_month_offset, v_interval_months) <> 0
    OR v_start <> (
      v_anchor + make_interval(months => v_month_offset)
    )::date
    OR v_end <> (
      v_anchor + make_interval(
        months => v_month_offset + v_interval_months
      )
    )::date
  THEN
    RAISE EXCEPTION 'Provider billing cadence mismatch';
  END IF;

  IF v_sub.current_period_start IS NOT DISTINCT FROM p_period_start
    AND v_sub.current_period_end IS NOT DISTINCT FROM p_period_end
  THEN
    NULL;

  ELSIF v_sub.current_period_end = p_period_start THEN

    IF NOT EXISTS (
      SELECT 1
      FROM public.gallaspy_subscription_payments p
      WHERE p.subscription_id = v_sub.id
        AND p.billing_period_start = v_sub.current_period_start
        AND p.billing_period_end = v_sub.current_period_end
        AND p.payment_status = 'completed'
        AND p.refunded_amount_cents = 0
        AND p.verified_at IS NOT NULL
        AND p.amount_cents = v_expected_amount
        AND p.currency = 'USD'
    ) THEN
      RAISE EXCEPTION 'Previous billing period requires reconciliation';
    END IF;

  ELSE
    RAISE EXCEPTION 'Nonconsecutive billing period';
  END IF;

  UPDATE public.gallaspy_standard_subscriptions
  SET
    current_period_start = p_period_start,
    current_period_end = p_period_end,
    subscription_status = 'active',
    updated_at = now()
  WHERE id = v_sub.id;

  SELECT public.gallaspy_record_verified_dues_v3(
    p_user_id,
    p_square_subscription_id,
    p_square_payment_id,
    p_square_invoice_id,
    p_amount_cents,
    p_period_start,
    p_period_end,
    p_paid_at,
    p_verified_at
  )
  INTO v_result;

  IF v_result IS DISTINCT FROM 'recorded' THEN
    RAISE EXCEPTION 'Atomic dues recording failed';
  END IF;

  RETURN 'recorded';
END;
$function$

CREATE OR REPLACE FUNCTION public.gallaspy_reserve_standard_enrollment_v2(p_user_id uuid, p_plan text)
 RETURNS TABLE(attempt_id uuid, idempotency_key uuid, enrollment_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_attempt public.gallaspy_standard_enrollment_attempts%ROWTYPE;
  v_initiation integer;
  v_initial integer;
  v_renewal integer;
  v_interval text;
BEGIN
  IF p_user_id IS NULL
     OR p_plan IS NULL
     OR p_plan NOT IN ('monthly', 'annual') THEN
    RAISE EXCEPTION 'Valid user and Standard Membership plan required';
  END IF;

  IF p_plan = 'monthly' THEN
    v_initiation := 25000;
    v_initial := 35000;
    v_renewal := 10000;
    v_interval := 'monthly';
  ELSE
    v_initiation := 0;
    v_initial := 100000;
    v_renewal := 100000;
    v_interval := 'annual';
  END IF;

  PERFORM 1
  FROM auth.users
  WHERE id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User does not exist';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.gallaspy_memberships m
    WHERE m.user_id = p_user_id
      AND (
        m.membership_type = 'falcon_society'
        OR m.membership_status IN ('approved', 'suspended')
      )
  ) THEN
    RAISE EXCEPTION 'Existing membership requires review';
  END IF;

  SELECT a.*
  INTO v_attempt
  FROM public.gallaspy_standard_enrollment_attempts a
  WHERE a.user_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.gallaspy_standard_enrollment_attempts (user_id)
    VALUES (p_user_id)
    RETURNING * INTO v_attempt;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.gallaspy_standard_subscriptions s
    WHERE s.user_id = p_user_id
      AND s.square_subscription_id IS NOT NULL
      AND s.square_subscription_id
          IS DISTINCT FROM v_attempt.square_subscription_id
  ) THEN
    RAISE EXCEPTION 'Existing subscription requires reconciliation';
  END IF;

  IF v_attempt.selected_plan IS NULL THEN
    IF v_attempt.enrollment_status <> 'reserved' THEN
      RAISE EXCEPTION 'Unbound enrollment must be reserved before choosing a plan';
    END IF;

    UPDATE public.gallaspy_standard_enrollment_attempts a
    SET
      selected_plan = p_plan,
      initiation_fee_cents = v_initiation,
      initial_payment_cents = v_initial,
      renewal_amount_cents = v_renewal,
      renewal_interval = v_interval,
      updated_at = now()
    WHERE a.id = v_attempt.id
      AND a.user_id = p_user_id
    RETURNING * INTO v_attempt;
  END IF;

  IF v_attempt.selected_plan IS DISTINCT FROM p_plan
     OR v_attempt.initiation_fee_cents IS DISTINCT FROM v_initiation
     OR v_attempt.initial_payment_cents IS DISTINCT FROM v_initial
     OR v_attempt.renewal_amount_cents IS DISTINCT FROM v_renewal
     OR v_attempt.renewal_interval IS DISTINCT FROM v_interval THEN
    RAISE EXCEPTION 'Existing enrollment plan or pricing does not match';
  END IF;

  RETURN QUERY
  SELECT
    v_attempt.id,
    v_attempt.idempotency_key,
    v_attempt.enrollment_status;
END;
$function$

CREATE OR REPLACE FUNCTION public.gallaspy_settle_membership_initiation_refund(p_refund_id text, p_payment_id text, p_amount_cents integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_payment public.gallaspy_membership_initiation_payments%ROWTYPE;
  v_existing public.gallaspy_membership_initiation_refunds%ROWTYPE;
  v_total bigint;
BEGIN
  IF p_refund_id IS NULL
    OR p_refund_id !~ '^[A-Za-z0-9_-]{1,255}$'
    OR p_payment_id IS NULL
    OR p_payment_id !~ '^[A-Za-z0-9_-]{1,255}$'
    OR p_amount_cents IS NULL
    OR p_amount_cents < 1
    OR p_amount_cents > 25000
  THEN
    RAISE EXCEPTION 'Invalid initiation refund attributes';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'gallaspy-membership-refund:' || p_refund_id,
      0
    )
  );

  IF EXISTS (
    SELECT 1
    FROM public.gallaspy_standard_membership_refunds
    WHERE square_refund_id = p_refund_id
  ) THEN
    RAISE EXCEPTION 'Refund already assigned to membership dues';
  END IF;

  SELECT * INTO v_payment
  FROM public.gallaspy_membership_initiation_payments
  WHERE square_payment_id = p_payment_id
  FOR UPDATE;

  IF NOT FOUND
    OR v_payment.membership_plan <> 'monthly'
    OR v_payment.amount_cents <> 25000
    OR v_payment.currency <> 'USD'
    OR v_payment.verified_at IS NULL
    OR v_payment.paid_at IS NULL
    OR v_payment.square_customer_id IS NULL
    OR v_payment.payment_status NOT IN (
      'completed',
      'requires_review'
    )
  THEN
    RAISE EXCEPTION 'No verified initiation payment';
  END IF;

  SELECT * INTO v_existing
  FROM public.gallaspy_membership_initiation_refunds
  WHERE square_refund_id = p_refund_id;

  IF FOUND THEN
    IF v_existing.initiation_payment_id <> v_payment.id
      OR v_existing.refund_amount_cents <> p_amount_cents
    THEN
      RAISE EXCEPTION 'Conflicting initiation refund replay';
    END IF;

    RETURN 'duplicate';
  END IF;

  SELECT COALESCE(SUM(refund_amount_cents), 0)
  INTO v_total
  FROM public.gallaspy_membership_initiation_refunds
  WHERE initiation_payment_id = v_payment.id;

  IF COALESCE(v_payment.refunded_amount_cents, 0) <> v_total THEN
    RAISE EXCEPTION 'Initiation refund history requires reconciliation';
  END IF;

  IF v_total + p_amount_cents > v_payment.amount_cents THEN
    RAISE EXCEPTION 'Refund exceeds initiation payment';
  END IF;

  INSERT INTO public.gallaspy_membership_initiation_refunds
  (
    square_refund_id,
    initiation_payment_id,
    refund_amount_cents,
    currency
  )
  VALUES (
    p_refund_id,
    v_payment.id,
    p_amount_cents,
    'USD'
  );

  UPDATE public.gallaspy_membership_initiation_payments
  SET
    payment_status = 'requires_review',
    refunded_amount_cents = v_total + p_amount_cents,
    updated_at = now()
  WHERE id = v_payment.id;

  RETURN CASE
    WHEN v_total + p_amount_cents = 25000
    THEN 'refunded'
    ELSE 'partially_refunded'
  END;
END;
$function$

CREATE OR REPLACE FUNCTION public.gallaspy_settle_standard_membership_refund(p_refund_id text, p_payment_id text, p_amount_cents integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_payment public.gallaspy_subscription_payments%ROWTYPE;
  v_existing public.gallaspy_standard_membership_refunds%ROWTYPE;
  v_total bigint;
  v_next text;
BEGIN
  IF p_refund_id IS NULL
    OR p_refund_id !~ '^[A-Za-z0-9_-]{1,255}$'
    OR p_payment_id IS NULL
    OR p_payment_id !~ '^[A-Za-z0-9_-]{1,255}$'
    OR p_amount_cents IS NULL
    OR p_amount_cents < 1
    OR p_amount_cents > 100000
  THEN
    RAISE EXCEPTION 'Invalid membership refund attributes';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'gallaspy-membership-refund:' || p_refund_id,
      0
    )
  );

  IF EXISTS (
    SELECT 1
    FROM public.gallaspy_membership_initiation_refunds
    WHERE square_refund_id = p_refund_id
  ) THEN
    RAISE EXCEPTION 'Refund already assigned to initiation payment';
  END IF;

  SELECT * INTO v_payment
  FROM public.gallaspy_subscription_payments
  WHERE square_payment_id = p_payment_id
  FOR UPDATE;

  IF NOT FOUND
    OR v_payment.amount_cents NOT IN (10000, 100000)
    OR v_payment.currency <> 'USD'
    OR v_payment.payment_status NOT IN (
      'completed',
      'partially_refunded',
      'refunded'
    )
  THEN
    RAISE EXCEPTION 'No eligible verified membership payment';
  END IF;

  SELECT * INTO v_existing
  FROM public.gallaspy_standard_membership_refunds
  WHERE square_refund_id = p_refund_id;

  IF FOUND THEN
    IF v_existing.subscription_payment_id <> v_payment.id
      OR v_existing.refund_amount_cents <> p_amount_cents
    THEN
      RAISE EXCEPTION 'Conflicting Square refund replay';
    END IF;

    RETURN 'duplicate';
  END IF;

  SELECT COALESCE(SUM(refund_amount_cents), 0)
  INTO v_total
  FROM public.gallaspy_standard_membership_refunds
  WHERE subscription_payment_id = v_payment.id;

  IF COALESCE(v_payment.refunded_amount_cents, 0) > v_total
    OR (
      v_payment.payment_status <> 'completed'
      AND v_total = 0
    )
  THEN
    RAISE EXCEPTION 'Previous refund requires reconciliation';
  END IF;

  IF v_total + p_amount_cents > v_payment.amount_cents THEN
    RAISE EXCEPTION 'Refund exceeds original payment';
  END IF;

  INSERT INTO public.gallaspy_standard_membership_refunds
  (
    square_refund_id,
    subscription_payment_id,
    refund_amount_cents,
    currency
  )
  VALUES (
    p_refund_id,
    v_payment.id,
    p_amount_cents,
    'USD'
  );

  v_next := CASE
    WHEN v_total + p_amount_cents = v_payment.amount_cents
    THEN 'refunded'
    ELSE 'partially_refunded'
  END;

  UPDATE public.gallaspy_subscription_payments
  SET
    payment_status = v_next,
    refunded_amount_cents = v_total + p_amount_cents
  WHERE id = v_payment.id;

  RETURN v_next;
END;
$function$
